WITH weeks AS (
  SELECT date_trunc('week', created)::date AS wk,
         COUNT(*) AS users
  FROM u
  WHERE created::date <= DATE '2026-07-12'
  GROUP BY 1
), last_two AS (
  SELECT * FROM weeks WHERE wk IN (DATE '2026-07-06', DATE '2026-06-29')
)
SELECT wk, users FROM last_two ORDER BY wk;

WITH weeks AS (
  SELECT date_trunc('week', ts)::date AS wk,
         COUNT(*) AS moments
  FROM evt
  WHERE ts::date <= DATE '2026-07-12'
  GROUP BY 1
), last_two AS (
  SELECT * FROM weeks WHERE wk IN (DATE '2026-07-06', DATE '2026-06-29')
)
SELECT wk, moments FROM last_two ORDER BY wk;
